import React from 'react';
import './ExecutiveSummary.css';

function ExecutiveSummary({ data }) {
  if (!data || !data.kpis) return null;

  const { kpis } = data;

  return (
    <div className="executive-summary-card">
      <div className="executive-summary-header">
        <div className="summary-title-wrapper">
          <svg className="summary-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M9 11L12 14L22 4" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
            <path d="M21 12V19C21 19.5304 20.7893 20.0391 20.4142 20.4142C20.0391 20.7893 19.5304 21 19 21H5C4.46957 21 3.96086 20.7893 3.58579 20.4142C3.21071 20.0391 3 19.5304 3 19V5C3 4.46957 3.21071 3.96086 3.58579 3.58579C3.96086 3.21071 4.46957 3 5 3H16" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          <h2 className="executive-summary-title">Executive Summary</h2>
        </div>
        <div className="summary-badge">AI-Powered Insights</div>
      </div>
      <div className="executive-summary-content">
        <p className="summary-paragraph">
          <strong>{kpis.notified_today || 0}</strong> patients notified today, with active monitoring and real-time intervention capabilities.
        </p>
        <p className="summary-paragraph">
          <strong>Weekly:</strong> Adherence is <strong>{kpis.adh_delta_weekly != null ? (kpis.adh_delta_weekly > 0 ? '+' : '') + kpis.adh_delta_weekly.toFixed(1) + '%' : 'N/A'}</strong> vs last week{kpis.adh_delta_weekly != null ? ` (${kpis.adh_delta_weekly > 0 ? 'improving' : kpis.adh_delta_weekly < 0 ? 'declining' : 'stable'})` : ''}.
        </p>
        <p className="summary-paragraph">
          <strong>Monthly (same period):</strong> Adherence is <strong>{kpis.adh_delta_monthly != null ? (kpis.adh_delta_monthly > 0 ? '+' : '') + kpis.adh_delta_monthly.toFixed(1) : (kpis.adh_delta != null ? (kpis.adh_delta > 0 ? '+' : '') + kpis.adh_delta?.toFixed(1) : '0.0')}%</strong> vs last month through the same day (e.g. Feb 1–15 vs Jan 1–15), indicating {kpis.adh_delta_monthly != null ? (kpis.adh_delta_monthly > 0 ? 'improving' : kpis.adh_delta_monthly < 0 ? 'declining' : 'stable') : (kpis.adh_delta > 0 ? 'improving' : kpis.adh_delta < 0 ? 'declining' : 'stable')} patient compliance.
        </p>
        <p className="summary-paragraph">
          High-risk patient trend: <strong>{kpis.hr_delta > 0 ? '+' : ''}{kpis.hr_delta || 0}</strong> change from last week, {kpis.hr_delta > 0 ? 'requiring increased attention' : kpis.hr_delta < 0 ? 'showing improvement' : 'remaining stable'}.
        </p>
      </div>
    </div>
  );
}

export default ExecutiveSummary;
